<?php require __DIR__.'/config/config.php';require __DIR__.'/config/helpers.php';$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10){$message='Email invalide ou mot de passe trop court (10 caractères minimum).';}else{$q=$pdo->prepare('SELECT id FROM users WHERE email=?');$q->execute([$email]);if($q->fetch()){$message='Cet email existe déjà. Connectez-vous avec ce compte ou choisissez un autre email.';}else{$q=$pdo->prepare("INSERT INTO users(nom,prenom,email,telephone,password,role) VALUES('Administrateur','Principal',?,NULL,?,'admin')");$q->execute([$email,password_hash($pass,PASSWORD_DEFAULT)]);$message='Compte administrateur créé. Supprimez maintenant le fichier installer_admin.php du dossier du projet.';}}}$pageTitle='Installation administrateur';require __DIR__.'/includes/header.php';?><section class="auth-wrap"><form class="auth-card" method="post"><?=csrf_field()?><span class="eyebrow">CONFIGURATION INITIALE</span><h1>Créer l’administrateur</h1><p>Utilisez cette page une seule fois après l’importation de la base de données.</p><?php if($message):?><div class="alert alert-info"><?=e($message)?></div><?php endif;?><label class="form-label">Email administrateur</label><input class="form-control mb-3" name="email" type="email" required><label class="form-label">Mot de passe (10 caractères minimum)</label><input class="form-control mb-3" name="password" type="password" minlength="10" required><button class="btn btn-primary">Créer le compte admin</button></form></section><?php require __DIR__.'/includes/footer.php';?>